/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * This function debounce the received function
 * @param { function } 	func				Function to be debounced
 * @param { number } 		wait				Time to wait before execut the function
 * @param { boolean } 	immediate		Param to define if the function will be executed immediately
 */
const debounce = <T, A extends any[]>(
  func: (...args: A) => void,
  wait?: number,
  immediate?: boolean,
) => {
  let timeout: NodeJS.Timeout | null = null
  let currentFunc = func

  const debounced = function debounced(this: T, ...args: A): void {
    const later = () => {
      timeout = null
      if (!immediate) {
        currentFunc.apply(this, args)
      }
    }

    if (immediate && !timeout) {
      /**
       * there's no need to clear the timeout
       * since we expect it to resolve and set `timeout = null`
       */
      currentFunc.apply(this, args)
      timeout = setTimeout(later, wait)
    }

    if (!immediate) {
      if (timeout) {
        clearTimeout(timeout)
      }
      timeout = setTimeout(later, wait)
    }
  }

  debounced.cancel = () => {
    /* c8 ignore start */
    if (!timeout) {
      return
    }
    /* c8 ignore end */
    clearTimeout(timeout)
    timeout = null
  }

  debounced.setCallback = (newFunc: (...args: A) => void) => {
    currentFunc = newFunc
  }

  return debounced
}

export default debounce
import React from 'react'
import { render, fireEvent, act, screen, waitFor } from '@testing-library/react'
import { TooltipController } from '../components/TooltipController'

export function advanceTimers(ms = 0) {
  act(() => {
    jest.advanceTimersByTime(ms)
  })
}

export function flushPendingTimers() {
  act(() => {
    jest.runOnlyPendingTimers()
  })
}

export async function flushMicrotasks() {
  await act(async () => {
    await Promise.resolve()
  })
}

export function fireWithTimers(callback, ms = 0) {
  act(() => {
    callback()
    if (ms) {
      jest.advanceTimersByTime(ms)
    }
  })
}

export function hoverAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.mouseEnter(anchor)
  }, ms)
}

export function unhoverAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.mouseLeave(anchor)
  }, ms)
}

export function clickAnchor(anchor, ms = 0) {
  fireWithTimers(() => {
    fireEvent.click(anchor)
  }, ms)
}

export async function waitForTooltip(id) {
  await waitFor(() => {
    expect(document.getElementById(id)).toBeInTheDocument()
  })
  return document.getElementById(id)
}

export async function waitForTooltipToClose(id) {
  await waitFor(() => {
    expect(document.getElementById(id)).not.toBeInTheDocument()
  })
}

export async function waitForTooltipToStopShowing(id) {
  await waitFor(() => {
    const tooltip = document.getElementById(id)
    expect(tooltip === null || tooltip.classList.contains('react-tooltip__closing')).toBe(true)
  })
}

export function renderTooltip({
  id = 'test-tooltip',
  anchorText = 'Hover Me',
  anchorProps = {},
  tooltipProps = {},
  anchor = <span data-tooltip-id={id}>{anchorText}</span>,
} = {}) {
  const view = render(
    <>
      {React.isValidElement(anchor)
        ? React.cloneElement(anchor, {
